  "constraints": [
    {
      "id": "R1",
      "category": "math",
      "alternatives": [
        "np.isclose(df['tcprtt'], df['synack'] + df['ackdat'])"
      ],
      "features": ["tcprtt", "synack", "ackdat"],
      "rationale": "TCP round-trip time is defined as the sum of synack and ackdat."
    },
    {
      "id": "R2",
      "category": "math",
      "alternatives": [
        "(df['dur'] <= 0) | np.isclose(df['sload'], (df['sbytes'] * 8) / df['dur'])"
      ],
      "features": ["sload", "sbytes", "dur"],
      "rationale": "Source load is defined as source bits per second, so sload = sbytes*8/dur."
    },
    {
      "id": "R3",
      "category": "math",
      "alternatives": [
        "(df['dur'] <= 0) | np.isclose(df['dload'], (df['dbytes'] * 8) / df['dur'])"
      ],
      "features": ["dload", "dbytes", "dur"],
      "rationale": "Destination load is defined as destination bits per second, so dload = dbytes*8/dur."
    },
    {
      "id": "R4",
      "category": "math",
      "alternatives": [
        "(df['spkts'] == 0) | (df['smean'] == df['sbytes'] // df['spkts'])",
        "(df['spkts'] == 0) | (df['smean'] == np.round(df['sbytes'] / df['spkts']).astype(int))",
        "(df['spkts'] == 0) | np.isclose(df['smean'], df['sbytes'] / df['spkts'])"
      ],
      "features": ["smean", "sbytes", "spkts"],
      "rationale": "Source mean packet size is defined as total source bytes divided by source packet count; integer rounding may vary."
    },
    {
      "id": "R5",
      "category": "math",
      "alternatives": [
        "(df['dpkts'] == 0) | (df['dmean'] == df['dbytes'] // df['dpkts'])",
        "(df['dpkts'] == 0) | (df['dmean'] == np.round(df['dbytes'] / df['dpkts']).astype(int))",
        "(df['dpkts'] == 0) | np.isclose(df['dmean'], df['dbytes'] / df['dpkts'])"
      ],
      "features": ["dmean", "dbytes", "dpkts"],
      "rationale": "Destination mean packet size is defined as total destination bytes divided by destination packet count; integer rounding may vary."
    },
    {
      "id": "R6",
      "category": "math",
      "alternatives": [
        "df['sloss'] <= df['spkts']"
      ],
      "features": ["sloss", "spkts"],
      "rationale": "Source retransmitted/dropped packets cannot exceed total source packets sent."
    },
    {
      "id": "R7",
      "category": "math",
      "alternatives": [
        "df['dloss'] <= df['dpkts']"
      ],
      "features": ["dloss", "dpkts"],
      "rationale": "Destination retransmitted/dropped packets cannot exceed total destination packets sent."
    },
    {
      "id": "R8",
      "category": "math",
      "alternatives": [
        "(df['spkts'] <= 1) | np.isclose(df['sinpkt'], (df['dur'] * 1000) / (df['spkts'] - 1))",
        "(df['spkts'] <= 1) | np.isclose(df['sinpkt'], df['dur'] / (df['spkts'] - 1))"
      ],
      "features": ["sinpkt", "dur", "spkts"],
      "rationale": "Source interpacket arrival time may be derived from duration and packet count; units (ms vs s) are ambiguous."
    },
    {
      "id": "R9",
      "category": "math",
      "alternatives": [
        "(df['dpkts'] <= 1) | np.isclose(df['dinpkt'], (df['dur'] * 1000) / (df['dpkts'] - 1))",
        "(df['dpkts'] <= 1) | np.isclose(df['dinpkt'], df['dur'] / (df['dpkts'] - 1))"
      ],
      "features": ["dinpkt", "dur", "dpkts"],
      "rationale": "Destination interpacket arrival time may be derived from duration and packet count; units (ms vs s) are ambiguous."
    },
    {
      "id": "R10",
      "category": "math",
      "alternatives": [
        "(df['dur'] <= 0) | np.isclose(df['rate'], (df['spkts'] + df['dpkts']) / df['dur'])",
        "(df['dur'] <= 0) | np.isclose(df['rate'], (df['sbytes'] + df['dbytes']) / df['dur'])",
        "(df['dur'] <= 0) | np.isclose(df['rate'], df['spkts'] / df['dur'])",
        "(df['dur'] <= 0) | np.isclose(df['rate'], df['sbytes'] / df['dur'])",
        "(df['dur'] <= 0) | np.isclose(df['rate'], (df['sbytes'] * 8) / df['dur'])",
        "(df['dur'] <= 0) | np.isclose(df['rate'], (df['spkts'] + df['dpkts']) * 1000 / df['dur'])"
      ],
      "features": ["rate", "dur", "spkts", "dpkts", "sbytes", "dbytes"],
      "rationale": "Rate is undocumented; plausible definitions include packets per second, bytes per second, or bits per second, with possible scaling."
    }
  ]
